extra_head_css:
.meme-workspace { display: flex; gap: 24px; flex-wrap: wrap; }
    .meme-sidebar { flex: 0 0 340px; display: flex; flex-direction: column; gap: 14px; }
    .meme-canvas-area { flex: 1; min-width: 300px; }
    @media (max-width: 768px) { .meme-workspace { flex-direction: column; } .meme-sidebar { flex: none; width: 100%; } }

    .template-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
    .template-btn {
      border: 2px solid var(--border-color); border-radius: 8px; padding: 6px;
      background: var(--bg-primary); cursor: pointer; transition: all .2s;
      display: flex; flex-direction: column; align-items: center; gap: 4px; font-size: .65rem;
      color: var(--text-secondary); overflow: hidden;
    }
    .template-btn:hover { border-color: var(--accent); }
    .template-btn.active { border-color: var(--accent); background: rgba(99,102,241,.1); }
    .template-btn img { width: 100%; aspect-ratio: 4/3; object-fit: cover; border-radius: 4px; }

    .text-inputs { display: flex; flex-direction: column; gap: 8px; }
    .text-inputs label { font-size: .75rem; color: var(--text-secondary); font-weight: 500; }
    .text-inputs input[type="text"] {
      width: 100%; padding: 8px 10px; border: 1px solid var(--border-color); border-radius: 6px;
      background: var(--bg-primary); color: var(--text-primary); font-size: .85rem;
    }

    .param-row { display: flex; align-items: center; gap: 10px; }
    .param-row label { font-size: .78rem; color: var(--text-secondary); min-width: 80px; }
    .param-row input[type="range"] { flex: 1; accent-color: var(--accent); }
    .param-row select {
      flex: 1; padding: 6px 8px; border: 1px solid var(--border-color); border-radius: 6px;
      background: var(--bg-primary); color: var(--text-primary); font-size: .82rem;
    }

    .preview-wrapper {
      background: #000; border: 1px solid var(--border-color); border-radius: 12px; padding: 16px;
      display: flex; align-items: center; justify-content: center; min-height: 350px; overflow: auto; position: relative;
    }
    .preview-wrapper canvas { max-width: 100%; max-height: 65vh; }

    .info-row { display: flex; gap: 12px; font-size: .8rem; color: var(--text-secondary); padding: 8px 12px; background: var(--bg-secondary); border-radius: 8px; margin-top: 12px; }
    .info-row span { display: flex; align-items: center; gap: 4px; }
